def bracket_count(pattern):
    n = len(pattern)
    def fill(i, opened):
        # opened: 지금까지 열었지만 아직 닫지 않은 괄호 수
        if opened < 0 or opened > n - i:
            return 0
        if i == n:
            return 1 if opened == 0 else 0
        answer = 0
        if pattern[i] in "(?":
            answer += fill(i + 1, opened + 1)
        if pattern[i] in ")?":
            answer += fill(i + 1, opened - 1)
        return answer
    return fill(0, 0)

