def sudoku4_count(board):
    work = [row[:] for row in board]
    def allowed(r, c, value):
        for i in range(4):
            if work[r][i] == value or work[i][c] == value:
                return False
        br, bc = (r // 2) * 2, (c // 2) * 2
        for nr in range(br, br + 2):
            for nc in range(bc, bc + 2):
                if work[nr][nc] == value:
                    return False
        return True
    # 먼저 고정된 숫자끼리 충돌하는지 검사한다.
    for r in range(4):
        for c in range(4):
            value = work[r][c]
            if value:
                work[r][c] = 0
                ok = allowed(r, c, value)
                work[r][c] = value
                if not ok:
                    return 0
    def fill(pos):
        if pos == 16:
            return 1
        r, c = divmod(pos, 4)
        if work[r][c] != 0:
            return fill(pos + 1)
        answer = 0
        for value in range(1, 5):
            if allowed(r, c, value):
                work[r][c] = value
                answer += fill(pos + 1)
                work[r][c] = 0
        return answer
    return fill(0)

